1	//! A permanent scrollbar for a scrolling list, as a narrow column beside it:
2	//! a square button at the top that scrolls up, a track whose thumb shows how
3	//! much of the list is in view and can be dragged or clicked to, and a square
4	//! button at the bottom that scrolls down. Lists that follow new output, like
5	//! a task's, add a button below that locks the scroll to the bottom.
6	
7	use std::cell::Cell;
8	use std::rc::Rc;
9	use std::time::{Duration, Instant};
10	
11	use gpui_kit::assets::IconName;
12	use gpui_kit::component::button::{Button, ButtonVariants as _};
13	use gpui_kit::component::{ActiveTheme as _, Selectable as _, Sizable as _, h_flex, v_flex};
14	use gpui_kit::prelude::FluentBuilder as _;
15	use gpui_kit::*;
16	
17	use crate::measured_list::MeasuredList;
18	
19	/// How wide the column is, which is also each button's width and height.
20	pub const COLUMN_WIDTH: Pixels = px(18.);
21	
22	/// How far a button scrolls the list.
23	const STEP: Pixels = px(48.);
24	
25	/// The shortest the thumb gets, so it can always be grabbed.
26	const MIN_THUMB: Pixels = px(16.);
27	
28	/// How long the pulse lasts when the scroll locks.
29	const PULSE_TIME: Duration = Duration::from_millis(900);
30	
31	/// What a scroll column scrolls: an element tracking a [`ScrollHandle`], or a
32	/// virtualized list that knows its rows' heights.
33	#[derive(Clone)]
34	pub enum Scroll {
35	    Handle(ScrollHandle),
36	    Measured(MeasuredList),
37	}
38	
39	impl From<&ScrollHandle> for Scroll {
40	    fn from(handle: &ScrollHandle) -> Self {
41	        Scroll::Handle(handle.clone())
42	    }
43	}
44	
45	impl From<&MeasuredList> for Scroll {
46	    fn from(list: &MeasuredList) -> Self {
47	        list.scroll()
48	    }
49	}
50	
51	impl Scroll {
52	    /// How far it is scrolled, negative going down.
53	    pub fn offset(&self) -> Point<Pixels> {
54	        match self {
55	            Scroll::Handle(handle) => handle.offset(),
56	            Scroll::Measured(list) => list.offset(),
57	        }
58	    }
59	
60	    /// How far it can scroll.
61	    pub fn max_offset(&self) -> Point<Pixels> {
62	        match self {
63	            Scroll::Handle(handle) => handle.max_offset(),
64	            Scroll::Measured(list) => list.max_offset(),
65	        }
66	    }
67	
68	    pub fn set_offset(&self, offset: Point<Pixels>) {
69	        match self {
70	            Scroll::Handle(handle) => handle.set_offset(offset),
71	            Scroll::Measured(list) => list.set_offset(offset),
72	        }
73	    }
74	
75	    /// The part of it in view.
76	    fn viewport(&self) -> Bounds<Pixels> {
77	        match self {
78	            Scroll::Handle(handle) => handle.bounds(),
79	            Scroll::Measured(list) => list.viewport(),
80	        }
81	    }
82	}
83	
84	/// The track's fill, and the thumb's under the pointer and while dragged. The
85	/// track is black laid over whatever the column sits on, so it is darker than
86	/// what is beneath it on any surface. The thumb at rest has no fill at all, so
87	/// it is the colour of that surface, as the buttons are, and white is laid over
88	/// it as it is hovered and grabbed.
89	#[derive(Clone, Copy, Debug, PartialEq)]
90	pub struct ScrollColors {
91	    pub track: Hsla,
92	    pub hover: Hsla,
93	    pub pressed: Hsla,
94	}
95	
96	pub fn scroll_colors(dark: bool) -> ScrollColors {
97	    let (black, white) = (hsla(0., 0., 0., 1.), hsla(0., 0., 1., 1.));
98	    if dark {
99	        ScrollColors {
100	            track: black.opacity(0.4),
101	            hover: white.opacity(0.035),
102	            pressed: white.opacity(0.07),
103	        }
104	    } else {
105	        ScrollColors {
106	            track: black.opacity(0.16),
107	            hover: white.opacity(0.18),
108	            pressed: white.opacity(0.35),
109	        }
110	    }
111	}
112	
113	/// Locks the scroll to the bottom (`true`) or unlocks it (`false`).
114	pub type SetLock = Rc<dyn Fn(bool, &mut Window, &mut App)>;
115	
116	/// `content`, which scrolls with `handle`, beside its scroll column. With
117	/// `fill`, it fills the space it is given; otherwise it is as tall as
118	/// `content`, which is expected to cap its own height. With `lock`, whether
119	/// the scroll is locked to the bottom and how to switch it, the column ends in
120	/// a button for that; scrolling the list by hand, with the wheel or the
121	/// column, locks it when that leaves the list at the bottom and breaks the lock
122	/// when it doesn't.
123	pub fn with_scrollbar(
124	    id: impl Into<SharedString>,
125	    handle: impl Into<Scroll>,
126	    content: impl IntoElement,
127	    fill: bool,
128	    lock: Option<(bool, SetLock)>,
129	    cx: &App,
130	) -> AnyElement {
131	    let handle: Scroll = handle.into();
132	    let follow = follower(&handle, &lock);
133	    let row = h_flex()
134	        .items_stretch()
135	        .w_full()
136	        .when(fill, |row| row.flex_1().min_h_0().h_full())
137	        .child(
138	            div()
139	                .flex_1()
140	                .min_w_0()
141	                .when(fill, |it| it.h_full())
142	                // Scrolling by hand locks or unlocks the scroll. This bubbles
143	                // up from the list, which has already taken the scroll.
144	                .when_some(follow, |content, follow| {
145	                    content.on_scroll_wheel(move |_, window, cx| follow(window, cx))
146	                })
147	                .child(content),
148	        )
149	        .child(scrollbar(id.into(), &handle, lock, cx));
150	    row.into_any_element()
151	}
152	
153	/// After the list is scrolled by hand: locks the scroll when the list is left
154	/// at the bottom, and unlocks it when it isn't. A list with nothing to scroll
155	/// keeps its lock as it is.
156	type Follow = Rc<dyn Fn(&mut Window, &mut App)>;
157	
158	fn follower(handle: &Scroll, lock: &Option<(bool, SetLock)>) -> Option<Follow> {
159	    let (_, set_lock) = lock.as_ref()?;
160	    let (handle, set_lock) = (handle.clone(), set_lock.clone());
161	    Some(Rc::new(move |window, cx| {
162	        let max = handle.max_offset().y;
163	        if max > px(0.) {
164	            set_lock(at_bottom(&handle), window, cx);
165	        }
166	    }))
167	}
168	
169	/// Whether the list is scrolled to its bottom, or past it before it is
170	/// clamped.
171	fn at_bottom(handle: &Scroll) -> bool {
172	    handle.offset().y <= -handle.max_offset().y + px(1.)
173	}
174	
175	/// The column itself.
176	fn scrollbar(
177	    id: SharedString,
178	    handle: &Scroll,
179	    lock: Option<(bool, SetLock)>,
180	    cx: &App,
181	) -> AnyElement {
182	    let theme = cx.theme();
183	    let border = theme.border;
184	    let colors = scroll_colors(theme.is_dark());
185	    let palette = *crate::theme::palette(cx);
186	    // A square button filling the track inside its line, with no lines of its
187	    // own; see [`in_track`].
188	    let square = |name: &str, icon: IconName| {
189	        Button::new(SharedString::from(format!("{id}-{name}")))
190	            .ghost()
191	            .xsmall()
192	            .icon(icon)
193	            .w(COLUMN_WIDTH - TRACK_LINE)
194	            .h(COLUMN_WIDTH - TRACK_LINE)
195	            .rounded_none()
196	    };
197	    // `button` sitting just inside the track, as the thumb does: the track's
198	    // line runs down beside it, and a pixel of the dark track lies between it
199	    // and the part of the track toward `gap_above` or below it.
200	    let in_track = |button: AnyElement, gap_above: bool| {
201	        let gap = || div().flex_none().h(TRACK_LINE).w_full().bg(colors.track);
202	        h_flex()
203	            .w(COLUMN_WIDTH)
204	            .h(COLUMN_WIDTH)
205	            .child(div().w(TRACK_LINE).h_full().flex_none().bg(border))
206	            .child(
207	                v_flex()
208	                    .flex_1()
209	                    .h_full()
210	                    .when(gap_above, |slot| slot.child(gap()))
211	                    .child(button)
212	                    .when(!gap_above, |slot| slot.child(gap())),
213	            )
214	    };
215	    let follow = follower(handle, &lock);
216	    let scroll_by = |delta: Pixels| {
217	        let handle = handle.clone();
218	        let follow = follow.clone();
219	        let press: Press = Rc::new(move |window: &mut Window, cx: &mut App| {
220	            let offset = handle.offset();
221	            let max = handle.max_offset().y;
222	            let y = (offset.y + delta).min(px(0.)).max(-max);
223	            handle.set_offset(point(offset.x, y));
224	            if let Some(follow) = &follow {
225	                follow(window, cx);
226	            }
227	            window.refresh();
228	        });
229	        press
230	    };
231	
232	    let track = canvas(
233	        // Where on the thumb it was grabbed, while it is being dragged. Kept
234	        // with the track from frame to frame, since each mouse move redraws
235	        // the column.
236	        |_, window, cx| {
237	            let grab = window
238	                .use_keyed_state("scroll-grab", cx, |_, _| Rc::new(Cell::new(None::<Pixels>)));
239	            // Whether the pointer was over the thumb when last drawn.
240	            let hovered =
241	                window.use_keyed_state("scroll-thumb-hover", cx, |_, _| Rc::new(Cell::new(false)));
242	            (grab, hovered)
243	        },
244	        {
245	            let handle = handle.clone();
246	            let follow = follow.clone();
247	            move |bounds,
248	                  (grab, hovered): (Entity<Rc<Cell<Option<Pixels>>>>, Entity<Rc<Cell<bool>>>),
249	                  window,
250	                  cx| {
251	                let grab = grab.read(cx).clone();
252	                let hovered = hovered.read(cx).clone();
253	                let geometry = Geometry::of(&handle, bounds);
254	                let thumb = thumb_bounds(&geometry, bounds);
255	                // The track is dark above and below the thumb, inside its line,
256	                // while the thumb is left the colour of what the column sits on.
257	                let inside = bounds.origin.x + TRACK_LINE;
258	                for (top, bottom) in [
259	                    (bounds.top(), thumb.top()),
260	                    (thumb.bottom(), bounds.bottom()),
261	                ] {
262	                    if bottom > top {
263	                        window.paint_quad(fill(
264	                            Bounds::new(point(inside, top), size(thumb.size.width, bottom - top)),
265	                            colors.track,
266	                        ));
267	                    }
268	                }
269	                // The line beside the list runs the track's full height, the
270	                // thumb never covering it.
271	                window.paint_quad(fill(
272	                    Bounds::new(bounds.origin, size(TRACK_LINE, bounds.size.height)),
273	                    border,
274	                ));
275	                // The thumb fills the track inside its line, square, with no
276	                // lines of its own, lightening while hovered or dragged.
277	                // Nothing is hovered while something else, like a sidebar's
278	                // edge, is being dragged across it.
279	                let is_hovered = !cx.has_active_drag() && thumb.contains(&window.mouse_position());
280	                hovered.set(is_hovered);
281	                if grab.get().is_some() {
282	                    // No edge beneath the pointer is offered while dragging.
283	                    window.set_window_cursor_style(CursorStyle::Arrow);
284	                    window.paint_quad(fill(thumb, colors.pressed));
285	                } else if is_hovered {
286	                    window.paint_quad(fill(thumb, colors.hover));
287	                }
288	                // The theme's faint bevel.
289	                for (edge, color) in
290	                    crate::theme::bevel_edges(thumb, crate::theme::Bevel::Raised, &palette)
291	                {
292	                    window.paint_quad(fill(edge, color));
293	                }
294	                // Moving on or off the thumb redraws it.
295	                window.on_mouse_event({
296	                    let (handle, hovered) = (handle.clone(), hovered.clone());
297	                    move |event: &MouseMoveEvent, _, window, _| {
298	                        let geometry = Geometry::of(&handle, bounds);
299	                        let thumb = thumb_bounds(&geometry, bounds);
300	                        if thumb.contains(&event.position) != hovered.get() {
301	                            window.refresh();
302	                        }
303	                    }
304	                });
305	
306	                window.on_mouse_event({
307	                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
308	                    move |event: &MouseDownEvent, phase, window, cx| {
309	                        if !bounds.contains(&event.position) {
310	                            return;
311	                        }
312	                        let geometry = Geometry::of(&handle, bounds);
313	                        let y = event.position.y;
314	                        // The thumb, or the track pressed off it, against any
315	                        // resize edge over it there: the smaller takes the
316	                        // press, taking it first when it is contested.
317	                        let on_thumb = y >= geometry.thumb_top
318	                            && y <= geometry.thumb_top + geometry.thumb_height;
319	                        let target = if on_thumb {
320	                            thumb_bounds(&geometry, bounds)
321	                        } else {
322	                            bounds
323	                        };
324	                        if !crate::hit_areas::wins_at(target, event.position, cx) {
325	                            return;
326	                        }
327	                        let contested = crate::hit_areas::resize_at(event.position, cx);
328	                        let turn = if contested {
329	                            DispatchPhase::Capture
330	                        } else {
331	                            DispatchPhase::Bubble
332	                        };
333	                        if phase != turn {
334	                            return;
335	                        }
336	                        if contested {
337	                            cx.stop_propagation();
338	                        }
339	                        // Grabbed where it was pressed; pressed off the thumb, the
340	                        // thumb first jumps to centre on the press.
341	                        let at = if y >= geometry.thumb_top
342	                            && y <= geometry.thumb_top + geometry.thumb_height
343	                        {
344	                            y - geometry.thumb_top
345	                        } else {
346	                            geometry.thumb_height / 2.
347	                        };
348	                        grab.set(Some(at));
349	                        geometry.scroll_thumb_to(&handle, y - at);
350	                        if let Some(follow) = &follow {
351	                            follow(window, cx);
352	                        }
353	                        window.refresh();
354	                    }
355	                });
356	                window.on_mouse_event({
357	                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
358	                    move |event: &MouseMoveEvent, _, window, cx| {
359	                        if let Some(at) = grab.get() {
360	                            if !event.dragging() {
361	                                grab.set(None);
362	                                return;
363	                            }
364	                            Geometry::of(&handle, bounds)
365	                                .scroll_thumb_to(&handle, event.position.y - at);
366	                            if let Some(follow) = &follow {
367	                                follow(window, cx);
368	                            }
369	                            window.refresh();
370	                        }
371	                    }
372	                });
373	                window.on_mouse_event({
374	                    let grab = grab.clone();
375	                    move |_: &MouseUpEvent, _, _, _| grab.set(None)
376	                });
377	            }
378	        },
379	    )
380	    .size_full();
381	
382	    let column = v_flex()
383	        .id(SharedString::from(format!("{id}-scroll-column")))
384	        .flex_none()
385	        .w(COLUMN_WIDTH)
386	        .child(in_track(
387	            bevelled(
388	                format!("{id}-scroll-up"),
389	                square("scroll-up", IconName::ChevronUp)
390	                    .tooltip("Scroll up")
391	                    .on_click({
392	                        let press = scroll_by(STEP);
393	                        move |_, window, cx| press(window, cx)
394	                    }),
395	                scroll_by(STEP),
396	            )
397	            .into_any_element(),
398	            false,
399	        ))
400	        .child(gpui_kit::TestSupportExt::test_support(
401	            div()
402	                .id(SharedString::from(format!("{id}-scroll-track")))
403	                .flex_1()
404	                .min_h(px(8.))
405	                .child(track),
406	        ))
407	        .child(in_track(
408	            bevelled(
409	                format!("{id}-scroll-down"),
410	                square("scroll-down", IconName::ChevronDown)
411	                    .tooltip("Scroll down")
412	                    .on_click({
413	                        let press = scroll_by(-STEP);
414	                        move |_, window, cx| press(window, cx)
415	                    }),
416	                scroll_by(-STEP),
417	            )
418	            .into_any_element(),
419	            true,
420	        ))
421	        .when_some(lock, |column, (locked, set_lock)| {
422	            let press: Press = {
423	                let set_lock = set_lock.clone();
424	                Rc::new(move |window, cx| set_lock(!locked, window, cx))
425	            };
426	            let button = square("scroll-lock", IconName::ArrowDownToLine)
427	                .selected(locked)
428	                .tooltip(if locked {
429	                    "Unlock the scroll from the bottom"
430	                } else {
431	                    "Lock the scroll to the bottom"
432	                })
433	                .on_click(move |_, window, cx| set_lock(!locked, window, cx));
434	            column.child(in_track(
435	                div()
436	                    .id(SharedString::from(format!("{id}-scroll-lock-pulse")))
437	                    .relative()
438	                    .child(pulse(locked, cx))
439	                    .child(button)
440	                    .child(over_edges(format!("{id}-scroll-lock-claim").into(), press))
441	                    .into_any_element(),
442	                true,
443	            ))
444	        });
445	    // Lets UI tests find the column; inert in normal builds.
446	    gpui_kit::TestSupportExt::test_support(column).into_any_element()
447	}
448	
449	/// `button`, with the theme's bevel while hovered, and its pressed bevel while
450	/// pressed with the pointer still over it. The bevel takes no mouse: it
451	/// watches the mouse before the button does.
452	fn bevelled(id: String, button: impl IntoElement, press: Press) -> impl IntoElement {
453	    use crate::theme::{Bevel, bevel_edges, palette};
454	    let key = SharedString::from(format!("{id}-bevel"));
455	    let overlay = canvas(
456	        move |_, window, cx| {
457	            // Whether the button was pressed, and not yet let go.
458	            window.use_keyed_state(key, cx, |_, _| Rc::new(Cell::new(false)))
459	        },
460	        move |bounds, pressed: Entity<Rc<Cell<bool>>>, window, cx| {
461	            let pressed = pressed.read(cx).clone();
462	            // Not while something else, like a sidebar's edge, is dragged.
463	            let hovered = !cx.has_active_drag() && bounds.contains(&window.mouse_position());
464	            let bevel = match (hovered, pressed.get()) {
465	                (true, true) => Some(Bevel::Pressed),
466	                (true, false) => Some(Bevel::Raised),
467	                (false, _) => None,
468	            };
469	            if let Some(bevel) = bevel {
470	                for (edge, color) in bevel_edges(bounds, bevel, palette(cx)) {
471	                    window.paint_quad(fill(edge, color));
472	                }
473	            }
474	            window.on_mouse_event({
475	                let pressed = pressed.clone();
476	                move |event: &MouseDownEvent, phase, window, cx| {
477	                    if phase == DispatchPhase::Capture
478	                        && event.button == MouseButton::Left
479	                        && crate::hit_areas::wins_at(bounds, event.position, cx)
480	                    {
481	                        pressed.set(true);
482	                        window.refresh();
483	                    }
484	                }
485	            });
486	            window.on_mouse_event({
487	                let pressed = pressed.clone();
488	                move |_: &MouseUpEvent, phase, window, _| {
489	                    if phase == DispatchPhase::Capture && pressed.replace(false) {
490	                        window.refresh();
491	                    }
492	                }
493	            });
494	            // Moving on or off the button redraws it.
495	            window.on_mouse_event(move |event: &MouseMoveEvent, _, window, _| {
496	                if bounds.contains(&event.position) != hovered {
497	                    window.refresh();
498	                }
499	            });
500	        },
501	    )
502	    .absolute()
503	    .top_0()
504	    .left_0()
505	    .size_full();
506	    div()
507	        .relative()
508	        .child(button)
509	        .child(overlay)
510	        .child(over_edges(format!("{id}-claim").into(), press))
511	}
512	
513	/// What pressing a button in the column does.
514	type Press = Rc<dyn Fn(&mut Window, &mut App)>;
515	
516	/// Lets the button it is laid over take a press, doing `press`, where a
517	/// resize edge beside the list overlaps it and has the larger hit area, as
518	/// the edge would otherwise take it: see [`crate::hit_areas`]. Over the
519	/// button there, the cursor is an arrow rather than the edge's.
520	fn over_edges(key: SharedString, press: Press) -> impl IntoElement {
521	    canvas(
522	        move |_, window, cx| {
523	            // Whether a press on the button is under way.
524	            window.use_keyed_state(key, cx, |_, _| Rc::new(Cell::new(false)))
525	        },
526	        move |bounds, claimed: Entity<Rc<Cell<bool>>>, window, cx| {
527	            let claimed = claimed.read(cx).clone();
528	            let contested = move |at: Point<Pixels>, cx: &App| {
529	                crate::hit_areas::resize_at(at, cx) && crate::hit_areas::wins_at(bounds, at, cx)
530	            };
531	            if !cx.has_active_drag() && contested(window.mouse_position(), cx) {
532	                window.set_window_cursor_style(CursorStyle::Arrow);
533	            }
534	            window.on_mouse_event({
535	                let claimed = claimed.clone();
536	                move |event: &MouseDownEvent, phase, window, cx| {
537	                    if phase == DispatchPhase::Capture
538	                        && event.button == MouseButton::Left
539	                        && contested(event.position, cx)
540	                    {
541	                        claimed.set(true);
542	                        cx.stop_propagation();
543	                        window.refresh();
544	                    }
545	                }
546	            });
547	            window.on_mouse_event({
548	                let press = press.clone();
549	                move |event: &MouseUpEvent, phase, window, cx| {
550	                    if phase == DispatchPhase::Capture && claimed.replace(false) {
