566	/// The glowing pulse that emanates from the lock button when the scroll
567	/// locks: a soft glow that blooms and fades, and two thin rings that ripple
568	/// out, the second just after the first. Drawn behind the button, over
569	/// whatever is beside the column, and never taking the mouse.
570	fn pulse(locked: bool, cx: &App) -> impl IntoElement {
571	    let color = cx.theme().ring;
572	    canvas(
573	        move |_, window, cx| {
574	            let state =
575	                window.use_keyed_state("pulse", cx, |_, _| Rc::new(Cell::new(Pulse::default())));
576	            let mut pulse = state.read(cx).get();
577	            let elapsed = pulse.observe(locked, Instant::now());
578	            state.read(cx).set(pulse);
579	            if elapsed.is_some() {
580	                window.request_animation_frame();
581	            }
582	            elapsed
583	        },
584	        move |bounds, elapsed, window, _| {
585	            let Some(elapsed) = elapsed else {
586	                return;
587	            };
588	            let frame = PulseFrame::at(elapsed);
589	            let center = bounds.center();
590	            let side = bounds.size.width.min(bounds.size.height);
591	            if frame.glow > 0. {
592	                window.paint_drop_shadows(
593	                    bounds,
594	                    (side / 2.).into(),
595	                    &[BoxShadow {
596	                        color: color.opacity(0.6 * frame.glow),
597	                        offset: point(px(0.), px(0.)),
598	                        blur_radius: px(10.),
599	                        spread_radius: px(2.) * frame.glow,
600	                        inset: false,
601	                    }],
602	                );
603	            }
604	            for ring in frame.rings {
605	                if ring.opacity <= 0. {
606	                    continue;
607	                }
608	                let diameter = side * ring.scale;
609	                let bounds = Bounds::new(
610	                    point(center.x - diameter / 2., center.y - diameter / 2.),
611	                    size(diameter, diameter),
612	                );
613	                window.paint_quad(quad(
614	                    bounds,
615	                    diameter / 2.,
616	                    transparent_black(),
617	                    px(ring.width),
618	                    color.opacity(ring.opacity),
619	                    BorderStyle::Solid,
620	                ));
621	            }
622	        },
623	    )
624	    .absolute()
625	    .inset_0()
626	}
