628	/// Whether the lock button is pulsing, from how the scroll was locked in the
629	/// frames before.
630	#[derive(Clone, Copy, Debug, Default)]
631	struct Pulse {
632	    /// Whether the scroll was locked last frame; `None` before the first.
633	    locked: Option<bool>,
634	    started: Option<Instant>,
635	}
636	
637	impl Pulse {
638	    /// Notes whether the scroll is locked `now`, returning how far into the
639	    /// pulse it is while one is under way. Locking starts one; a list first
640	    /// shown locked doesn't, and unlocking stops one.
641	    fn observe(&mut self, locked: bool, now: Instant) -> Option<Duration> {
642	        if locked && self.locked == Some(false) {
643	            self.started = Some(now);
644	        }
645	        if !locked {
646	            self.started = None;
647	        }
648	        self.locked = Some(locked);
649	        let elapsed = self
650	            .started
651	            .map(|started| now.saturating_duration_since(started));
652	        let elapsed = elapsed.filter(|elapsed| *elapsed < PULSE_TIME);
653	        if elapsed.is_none() {
654	            self.started = None;
655	        }
656	        elapsed
657	    }
658	}
