660	/// One frame of the pulse.
661	#[derive(Debug, PartialEq)]
662	struct PulseFrame {
663	    /// How strong the glow is, from 0 to 1.
664	    glow: f32,
665	    rings: [Ring; 2],
666	}
667	
668	/// One of the pulse's rings, sized against the button.
669	#[derive(Debug, PartialEq)]
670	struct Ring {
671	    scale: f32,
672	    opacity: f32,
673	    width: f32,
674	}
675	
676	impl PulseFrame {
677	    /// How long the glow takes to bloom, and then to fade.
678	    const BLOOM: f32 = 0.12;
679	    const FADE: f32 = 0.5;
680	    /// When each ring sets out, and how long it takes to spread.
681	    const RING_DELAYS: [f32; 2] = [0., 0.16];
682	    const RING_TIME: f32 = 0.7;
683	    /// How large a ring grows, against the button.
684	    const RING_SCALE: f32 = 2.8;
685	
686	    fn at(elapsed: Duration) -> Self {
687	        let t = elapsed.as_secs_f32();
688	        let glow = if t < Self::BLOOM {
689	            ease_out_cubic(t / Self::BLOOM)
690	        } else {
691	            1. - ease_in_out(((t - Self::BLOOM) / Self::FADE).min(1.))
692	        };
693	        let rings = Self::RING_DELAYS.map(|delay| {
694	            let progress = ((t - delay) / Self::RING_TIME).clamp(0., 1.);
695	            if t < delay {
696	                return Ring {
697	                    scale: 1.,
698	                    opacity: 0.,
699	                    width: 0.,
700	                };
701	            }
702	            let spread = ease_out_quint()(progress);
703	            let left = 1. - progress;
704	            Ring {
705	                scale: 1. + (Self::RING_SCALE - 1.) * spread,
706	                opacity: 0.7 * left * left,
707	                width: 0.75 + 1.25 * left,
708	            }
709	        });
710	        Self {
711	            glow: glow.clamp(0., 1.),
712	            rings,
713	        }
714	    }
715	}
716	
717	fn ease_out_cubic(t: f32) -> f32 {
718	    1. - (1. - t.clamp(0., 1.)).powi(3)
719	}
