721	/// The width of the line down the track's side against the list.
722	const TRACK_LINE: Pixels = px(1.);
723	
724	/// The thumb in a track at `track`: inside the track's line, never over it.
725	fn thumb_bounds(geometry: &Geometry, track: Bounds<Pixels>) -> Bounds<Pixels> {
726	    Bounds::new(
727	        point(track.origin.x + TRACK_LINE, geometry.thumb_top),
728	        size(
729	            (track.size.width - TRACK_LINE).max(px(0.)),
730	            geometry.thumb_height,
731	        ),
732	    )
733	}
