735	/// Where the thumb sits in a track, for a list scrolled as `handle` is.
736	struct Geometry {
737	    track: Bounds<Pixels>,
738	    thumb_top: Pixels,
739	    thumb_height: Pixels,
740	    /// How far the list scrolls.
741	    max: Pixels,
742	}
743	
744	impl Geometry {
745	    fn of(handle: &Scroll, track: Bounds<Pixels>) -> Self {
746	        let viewport = handle.viewport().size.height;
747	        let max = handle.max_offset().y.max(px(0.));
748	        let content = viewport + max;
749	        let height = track.size.height;
750	        // All of the list in view fills the track.
751	        let thumb_height = if content <= px(0.) {
752	            height
753	        } else {
754	            (height * (viewport / content)).max(MIN_THUMB).min(height)
755	        };
756	        let scrolled = (-handle.offset().y).max(px(0.)).min(max);
757	        let room = height - thumb_height;
758	        let thumb_top = if max > px(0.) {
759	            track.origin.y + room * (scrolled / max)
760	        } else {
761	            track.origin.y
762	        };
763	        Self {
764	            track,
765	            thumb_top,
766	            thumb_height,
767	            max,
768	        }
769	    }
770	
771	    /// Scrolls the list so the thumb's top is at `top`.
772	    fn scroll_thumb_to(&self, handle: &Scroll, top: Pixels) {
773	        let room = self.track.size.height - self.thumb_height;
774	        if room <= px(0.) || self.max <= px(0.) {
775	            return;
776	        }
777	        let fraction = ((top - self.track.origin.y) / room).clamp(0., 1.);
778	        let offset = handle.offset();
779	        handle.set_offset(point(offset.x, -(self.max * fraction)));
780	    }
781	}
